contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, bool freeze, address other, uint256 amount) public payable {
        require(other != address(0), "other must be nonzero");
        require(target != other, "target and other must differ");
        require(!c.frozenAccount(target), "target must initially be unfrozen");

        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 balTargetBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;
        uint256 balOtherBefore = c.balanceOf(other); if (__ESBMC_reverted()) return;

        c.freezeAccount(target, freeze); if (__ESBMC_reverted()) return;

        assert(c.totalSupply() == supplyBefore && c.balanceOf(target) == balTargetBefore && c.balanceOf(other) == balOtherBefore && c.frozenAccount(target) == freeze);
    }

    receive() external payable {}
}

